package servicio; import java.sql.*; import java.time.*; import config.ConexionBD; import dao.*; import negocio.*; public class IdentidadDeportivaService { private final PerfilJugadorDAO perfiles; private final CategoriaDeportivaDAO categorias; private final JugadorCategoriaDAO historial; private final ProveedorConexion conexiones; public IdentidadDeportivaService(){this(new PerfilJugadorDAOMySQL(),new CategoriaDeportivaDAOMySQL(),new JugadorCategoriaDAOMySQL(),ConexionBD::obtenerConexion);} public IdentidadDeportivaService(PerfilJugadorDAO p,CategoriaDeportivaDAO c,JugadorCategoriaDAO h,ProveedorConexion x){if(p==null||c==null||h==null||x==null)throw new IllegalArgumentException("Las dependencias son obligatorias.");perfiles=p;categorias=c;historial=h;conexiones=x;} public PerfilJugador crearDefinitivo(long clienteId,String nombre){if(clienteId<=0)throw new IllegalArgumentException("El cliente es invalido.");PerfilJugador p=new PerfilJugador();p.setClienteId(clienteId);p.setEstado(EstadoPerfilJugador.DEFINITIVO);p.setNombrePublico(nombre);p.setVinculacionRevisada(false);return guardar(p);} public PerfilJugador crearProvisional(String nombre){PerfilJugador p=new PerfilJugador();p.setEstado(EstadoPerfilJugador.PROVISIONAL);p.setNombrePublico(nombre);return guardar(p);} private PerfilJugador guardar(PerfilJugador p){try(Connection c=conexiones.obtener()){perfiles.guardar(c,p);return p;}catch(SQLException e){throw new RuntimeException("No se pudo crear la identidad deportiva.",e);}} public JugadorCategoria asignarCategoria(long perfilId,long categoriaId,LocalDate desde,OrigenJugadorCategoria origen,String motivo,Long usuarioId){if(perfilId<=0||categoriaId<=0||desde==null||origen==null||motivo==null||motivo.isBlank())throw new IllegalArgumentException("La asignacion deportiva es incompleta.");try(Connection c=conexiones.obtener()){c.setAutoCommit(false);try{if(perfiles.buscar(c,perfilId)==null)throw new IllegalArgumentException("El perfil no existe.");CategoriaDeportiva cat=categorias.buscar(c,categoriaId);if(cat==null||!cat.isActivo())throw new IllegalArgumentException("La categoria no existe o esta inactiva.");historial.finalizarVigente(c,perfilId,desde.minusDays(1));JugadorCategoria x=new JugadorCategoria();x.setPerfilJugadorId(perfilId);x.setCategoriaDeportivaId(categoriaId);x.setFechaDesde(desde);x.setEstado(EstadoJugadorCategoria.VIGENTE);x.setOrigen(origen);x.setMotivo(motivo.trim());x.setUsuarioResponsableId(usuarioId);historial.guardar(c,x);c.commit();return x;}catch(RuntimeException|SQLException e){try{c.rollback();}catch(SQLException r){e.addSuppressed(r);}throw e;}finally{try{c.setAutoCommit(true);}catch(SQLException ignored){}}}catch(SQLException e){throw new RuntimeException("No se pudo asignar la categoria deportiva.",e);}} @FunctionalInterface public interface ProveedorConexion{Connection obtener()throws SQLException;} }
